def run_study(bars, lookbacks, cost_bp, n_holdout=252):
    research, held_out = split_holdout(bars, n_holdout)
    vault = Vault(held_out)
    best = max(lookbacks, key=lambda L: net_sharpe(research, L, cost_bp))
    m_research = study_metrics(research, best, cost_bp)
    m_held = study_metrics(vault.open(), best, cost_bp)    # the only look
    return {"best_lookback": best, "research": m_research,
            "held_out": m_held, "n_trials": len(lookbacks)}

